CREATE OR REPLACE FUNCTION hermes.registrar_movimiento_pos(p_mov_id bigint)
 RETURNS bigint
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'hermes'
AS $function$
declare m public.movimiento_caja%rowtype; p_id bigint; c_id bigint; pos_id bigint; a record;
 rest numeric; intent jsonb; apps jsonb; pedido_cliente bigint;
begin
 select * into m from public.movimiento_caja where id=p_mov_id;
 if not found or m.tipo::text<>'ANTICIPO' then raise exception 'Movimiento no es un cobro de cliente'; end if;
 pos_id:=m.cliente_id;
 if m.pedido_id is not null then
   select cliente_id into pedido_cliente from public.pedido where id=m.pedido_id;
   if pos_id is not null and pos_id is distinct from pedido_cliente then raise exception 'Pedido y cliente no coinciden'; end if;
   pos_id:=pedido_cliente;
 end if;
 if pos_id is null then raise exception 'Cobro sin cliente'; end if;
 -- Los clientes actuales indican expresamente que retail queda solo en caja.
 -- Los clientes anteriores mantienen el contrato de la RPC existente.
 if coalesce((m.hermes_intencion->>'excluir_retail')::boolean,false)
   and exists(select 1 from public.cliente where id=pos_id and tipo_precio::text='retail') then
   if jsonb_array_length(coalesce(nullif(m.hermes_intencion->'aplicaciones','null'::jsonb),'[]'::jsonb))>0 then
     raise exception 'Los clientes retail no tienen partidas en el conciliador';
   end if;
   return null;
 end if;
 c_id:=hermes.asegurar_cliente_pos(pos_id);
 perform 1 from hermes.cliente where id=c_id for update;
 select id into p_id from hermes.pago where idempotencia_clave='pos-pago-mov-'||m.id;
 if p_id is not null then
   if not exists(select 1 from hermes.pago where id=p_id and cliente_id=c_id and monto=m.monto and medio::text=m.metodo::text) then
     raise exception 'El movimiento ya tiene un pago con datos diferentes';
   end if;
   return p_id;
 end if;
 intent:=coalesce(m.hermes_intencion,'{}'::jsonb);
 insert into hermes.pago(cliente_id,medio,monto,estado,fecha_recepcion,referencia,idempotencia_clave,creado_por,no_imputar)
 values(c_id,m.metodo::text::hermes.medio_pago,m.monto,'PROPUESTO',
   (m.creado_en at time zone 'America/La_Paz')::date,
   coalesce(nullif(intent->>'referencia',''),m.nota,'Cobro POS'),
   'pos-pago-mov-'||m.id,coalesce(m.creado_por,'pos'),coalesce((intent->>'no_imputar')::boolean,false))
 returning id into p_id;
 apps:=nullif(intent->'aplicaciones','null'::jsonb);
 if coalesce((intent->>'no_imputar')::boolean,false) then
   if apps is not null and jsonb_array_length(apps)>0 then raise exception 'Un anticipo sin imputación no admite reparto'; end if;
 elsif apps is not null then
   perform hermes.imputar_pago_pos_interno(p_id,apps,m.creado_por);
 elsif m.pedido_id is not null then
   rest:=m.monto;
   for a in select ve.partida_id,ve.pendiente from hermes.v_partida_estado ve
      where ve.cliente_id=c_id and ve.pedido_id=m.pedido_id and ve.estado='ABIERTA' and ve.pendiente>0
      order by ve.creado_en,ve.partida_id loop
     exit when rest<=0;
     insert into hermes.pago_aplicacion(pago_id,partida_id,monto) values(p_id,a.partida_id,least(rest,a.pendiente));
     rest:=rest-least(rest,a.pendiente);
   end loop;
 end if;
 return p_id;
end $function$

CREATE OR REPLACE FUNCTION public.cobrar_pedido_vendedor(p_pedido_ids bigint[], p_lineas jsonb, p_pagos jsonb, p_sesion_caja_id bigint, p_idempotencia text, p_quitadas jsonb DEFAULT '[]'::jsonb, p_descuento_total numeric DEFAULT 0, p_cliente_id bigint DEFAULT NULL::bigint, p_motivo_reserva text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare
  c_tope constant numeric := 0.10;
  v_uid  uuid := auth.uid();
  v_rol  text := app_rol_actual();
  v_usuario text;
  v_ses  sesion_caja%rowtype;
  v_ids  bigint[];
  v_ped  pedido_vendedor%rowtype;
  v_n    int := 0;
  v_l    jsonb;
  v_ix   int := 0;
  v_plid bigint;
  v_pl   pedido_vendedor_linea%rowtype;
  v_vistas bigint[] := '{}';
  v_prod producto%rowtype;
  v_pres presentacion%rowtype;
  v_unit numeric; v_cant numeric; v_lista numeric; v_min numeric; v_motivo text;
  v_out  jsonb := '[]'::jsonb;
  v_meta jsonb := '[]'::jsonb;
  v_q    jsonb;
  v_res  jsonb;
  v_venta venta%rowtype;
  v_vendedor uuid;
begin
  if v_rol is null or v_rol not in ('cajero', 'gerente', 'admin') then
    raise exception 'No autorizado para cobrar' using errcode = '42501';
  end if;
  if p_idempotencia is null or btrim(p_idempotencia) = '' or length(p_idempotencia) > 180 then
    raise exception 'Clave de idempotencia obligatoria (máx. 180 caracteres)';
  end if;
  select array_agg(distinct x order by x) into v_ids from unnest(p_pedido_ids) x where x is not null;
  if v_ids is null then
    raise exception 'Hay que indicar al menos un pedido a cobrar';
  end if;
  if p_lineas is null or jsonb_typeof(p_lineas) <> 'array' or jsonb_array_length(p_lineas) = 0 then
    raise exception 'p_lineas debe ser un array no vacío';
  end if;
  if p_quitadas is null or jsonb_typeof(p_quitadas) <> 'array' then
    raise exception 'p_quitadas debe ser un array';
  end if;

  perform pg_advisory_xact_lock(hashtextextended('cobro_pdv:' || p_idempotencia, 0));

  -- Reintento: la venta ya existe con esta clave y cerró estos mismos pedidos.
  select * into v_venta from venta where idempotencia_clave = p_idempotencia;
  if found then
    if (select count(*) from pedido_vendedor
         where id = any(v_ids) and estado = 'COBRADO' and venta_id = v_venta.id) = array_length(v_ids, 1) then
      return jsonb_build_object('reintento', true, 'venta_id', v_venta.id, 'numero', v_venta.numero,
                                'subtotal', v_venta.subtotal, 'descuento_total', v_venta.descuento_total,
                                'total', v_venta.total, 'pedidos', to_jsonb(v_ids),
                                'vendedor_id', v_venta.vendedor_id);
    end if;
    raise exception 'La clave de idempotencia ya se usó en otra venta';
  end if;

  select * into v_ses from sesion_caja where id = p_sesion_caja_id;
  if not found or v_ses.estado <> 'ABIERTA' then
    raise exception 'No hay una sesión de caja abierta (%).', p_sesion_caja_id;
  end if;
  if v_rol = 'cajero' and v_ses.cajero_id is distinct from v_uid then
    raise exception 'Solo puedes cobrar en tu propio turno';
  end if;
  select coalesce(email, 'sistema') into v_usuario from perfil where id = v_uid;

  for v_ped in select * from pedido_vendedor where id = any(v_ids) order by id for update loop
    v_n := v_n + 1;
    if v_ped.estado <> 'EN_CAJA' or v_ped.sesion_caja_id is distinct from p_sesion_caja_id then
      raise exception 'El pedido % no está tomado en esta caja', v_ped.numero_dia;
    end if;
  end loop;
  if v_n <> array_length(v_ids, 1) then
    raise exception 'Alguno de los pedidos indicados no existe';
  end if;

  for v_l in select * from jsonb_array_elements(p_lineas) loop
    v_ix := v_ix + 1;
    v_plid := nullif(v_l ->> 'pedido_linea_id', '')::bigint;
    v_unit := (v_l ->> 'precio_unitario')::numeric;
    v_lista := null; v_min := null; v_motivo := null;

    if v_plid is not null then
      select * into v_pl from pedido_vendedor_linea where id = v_plid and pedido_id = any(v_ids);
      if not found then
        raise exception 'La línea % no pertenece a los pedidos que se están cobrando', v_plid;
      end if;
      if v_plid = any(v_vistas) then
        raise exception 'La línea % del pedido viene repetida', v_plid;
      end if;
      v_vistas := v_vistas || v_plid;
      if not coalesce((v_l ->> 'verificada')::boolean, false) then
        raise exception 'Falta verificar la línea % del pedido antes de cobrar', v_pl.orden;
      end if;
      if not v_pl.es_personalizado
         and nullif(v_l ->> 'producto_id', '')::bigint is distinct from v_pl.producto_id then
        raise exception 'La línea % del pedido no puede cambiar de producto: quítala y agrega el producto nuevo', v_pl.orden;
      end if;
    end if;

    if coalesce((v_l ->> 'es_personalizado')::boolean, false) then
      v_cant := coalesce((v_l ->> 'cantidad_base')::numeric, (v_l ->> 'cantidad')::numeric);
    else
      select * into v_prod from producto where id = (v_l ->> 'producto_id')::bigint;
      if not found then
        raise exception 'Línea %: el producto % no existe', v_ix, v_l ->> 'producto_id';
      end if;
      if nullif(v_l ->> 'presentacion_id', '') is null then
        select * into v_pres from presentacion where producto_id = v_prod.id and es_base and activo limit 1;
        v_cant := coalesce((v_l ->> 'cantidad_base')::numeric, (v_l ->> 'cantidad')::numeric);
      else
        select * into v_pres from presentacion
         where id = (v_l ->> 'presentacion_id')::bigint and producto_id = v_prod.id and activo;
        v_cant := (v_l ->> 'cantidad_presentacion')::numeric;
      end if;
      if not found then
        raise exception '%: la presentación no existe o no es de este producto', v_prod.nombre;
      end if;

      v_lista := case when coalesce(v_prod.precio_base, 0) > 0
                      then round(v_prod.precio_base * v_pres.factor_unidad_base, 2) end;
      v_min := case when v_lista is not null and v_pres.es_base
                    then round(v_lista * (1 - c_tope), 2) end;
      -- El cajero no tiene tope, pero pasar del 10 % deja escrito el porqué.
      if v_min is not null and v_unit < v_min then
        v_motivo := nullif(btrim(v_l ->> 'motivo_descuento'), '');
        if v_motivo is null then
          raise exception '%: Bs % está más de % %% por debajo de la lista (Bs %). Falta el motivo del descuento',
            v_prod.nombre, v_unit, round(c_tope * 100), v_lista
            using errcode = 'check_violation';
        end if;
      end if;
      -- La lista la pone el servidor: el POS manda como "lista" el precio cobrado.
      if v_lista is not null then
        v_l := v_l || jsonb_build_object('precio_lista', v_lista);
      end if;
    end if;

    v_out := v_out || jsonb_build_array(v_l);
    v_meta := v_meta || jsonb_build_array(jsonb_build_object(
                'ix', v_ix, 'plid', v_plid, 'cant', v_cant, 'unit', v_unit, 'motivo', left(v_motivo, 200)));
  end loop;

  for v_q in select * from jsonb_array_elements(p_quitadas) loop
    v_plid := nullif(v_q ->> 'pedido_linea_id', '')::bigint;
    perform 1 from pedido_vendedor_linea where id = v_plid and pedido_id = any(v_ids);
    if not found then
      raise exception 'La línea quitada % no pertenece a los pedidos que se están cobrando', v_q ->> 'pedido_linea_id';
    end if;
    if v_plid = any(v_vistas) then
      raise exception 'La línea % del pedido figura cobrada y quitada a la vez', v_plid;
    end if;
    v_vistas := v_vistas || v_plid;
  end loop;

  select count(*) into v_n from pedido_vendedor_linea where pedido_id = any(v_ids);
  if v_n <> coalesce(array_length(v_vistas, 1), 0) then
    raise exception 'Faltan % línea(s) del pedido por verificar o quitar', v_n - coalesce(array_length(v_vistas, 1), 0);
  end if;

  v_res := _registrar_venta_nucleo(
    v_out, p_pagos, p_sesion_caja_id, p_cliente_id, coalesce(p_descuento_total, 0),
    v_usuario, p_idempotencia, nullif(btrim(p_motivo_reserva), '') is not null, nullif(btrim(p_motivo_reserva), ''));
  select * into v_venta from venta where id = (v_res ->> 'venta_id')::bigint;

  -- El núcleo inserta exactamente una venta_linea por elemento y en el mismo orden:
  -- la posición las empareja con las líneas del pedido.
  select count(*) into v_n from venta_linea where venta_id = v_venta.id;
  if v_n <> jsonb_array_length(v_out) then
    raise exception 'La venta quedó con % líneas y se enviaron %', v_n, jsonb_array_length(v_out);
  end if;

  -- venta_linea.precio_modificado es una columna generada (precio_unitario <> precio_lista):
  -- con la lista puesta por el servidor se marca sola, no hay que escribirla.

  with vl as (
    select id, row_number() over (order by id) as rn from venta_linea where venta_id = v_venta.id
  ), m as (
    select * from jsonb_to_recordset(v_meta) as x(ix int, plid bigint, cant numeric, unit numeric, motivo text)
  )
  update pedido_vendedor_linea l
     set resultado = 'COBRADA', venta_linea_id = vl.id, cantidad_final = m.cant, precio_final = m.unit
    from m join vl on vl.rn = m.ix
   where m.plid is not null and l.id = m.plid;

  insert into venta_evento (venta_id, linea_id, accion, motivo, usuario)
  select v_venta.id, vl.id, 'DESCUENTO_SOBRE_TOPE', m.motivo, v_usuario
    from jsonb_to_recordset(v_meta) as m(ix int, motivo text)
    join (select id, row_number() over (order by id) as rn from venta_linea where venta_id = v_venta.id) vl
      on vl.rn = m.ix
   where m.motivo is not null;

  update pedido_vendedor_linea l
     set resultado = 'QUITADA', motivo_caja = left(nullif(btrim(q.motivo), ''), 200)
    from jsonb_to_recordset(p_quitadas) as q(pedido_linea_id bigint, motivo text)
   where l.id = q.pedido_linea_id;

  update pedido_vendedor
     set estado = 'COBRADO', venta_id = v_venta.id, cobrado_en = now(), actualizado_en = now()
   where id = any(v_ids);

  -- Un solo vendedor detrás de la venta: queda en venta.vendedor_id.
  select case when count(distinct vendedor_id) = 1 then min(vendedor_id::text)::uuid end
    into v_vendedor from pedido_vendedor where id = any(v_ids);
  if v_vendedor is not null then
    update venta set vendedor_id = v_vendedor where id = v_venta.id;
  end if;

  insert into venta_evento (venta_id, accion, motivo, usuario)
  values (v_venta.id, 'PEDIDO_VENDEDOR',
          'Pedido(s) de vendedor: ' || (select string_agg('PDV-' || x, ', ' order by x) from unnest(v_ids) x),
          v_usuario);

  return v_res || jsonb_build_object('reintento', false, 'pedidos', to_jsonb(v_ids), 'vendedor_id', v_vendedor);
end;
$function$

CREATE OR REPLACE FUNCTION public.cobrar_vtd(p_venta_ids bigint[], p_sesion_caja_id bigint, p_pagos jsonb, p_idempotencia text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_rol        text;
  v_ses        sesion_caja%rowtype;
  v_perfil     perfil%rowtype;
  v_usuario    text;
  v_ids        bigint[];
  v_venta      venta%rowtype;
  v_total      numeric := 0;
  v_pagado     numeric := 0;
  v_cambio     numeric := 0;
  v_pago       jsonb;
  v_metodo     metodo_pago;
  v_rest_pago  numeric;
  v_rest_venta numeric;
  v_toma       numeric;
  v_verif      text;
  v_recibido   numeric;
  v_n          int := 0;
  v_idx        int;
  v_resto      jsonb := '[]'::jsonb;
  v_ventas_out jsonb := '[]'::jsonb;
  v_previa     jsonb;
begin
  v_rol := app_rol_actual();
  if v_rol is null or v_rol not in ('cajero', 'gerente', 'admin') then
    raise exception 'No autorizado para cobrar';
  end if;

  if p_idempotencia is null or btrim(p_idempotencia) = '' or length(p_idempotencia) > 180 then
    raise exception 'Clave de idempotencia obligatoria (máx. 180 caracteres)';
  end if;
  perform pg_advisory_xact_lock(hashtextextended('cobro_vtd:' || p_idempotencia, 0));

  -- Reintento: si ya se cobró con esta clave, devolver lo mismo sin duplicar.
  select jsonb_build_object(
           'reintento', true,
           'ventas', jsonb_agg(distinct v.numero),
           'total', sum(m.monto))
    into v_previa
    from movimiento_caja m join venta v on v.id = m.venta_id
   where m.idempotencia_clave like 'cobro_vtd:' || p_idempotencia || ':%';
  if v_previa ->> 'total' is not null then
    return v_previa;
  end if;

  -- Sesión: abierta; un cajero solo cobra en su propio turno.
  select * into v_ses from sesion_caja where id = p_sesion_caja_id;
  if not found or v_ses.estado <> 'ABIERTA' then
    raise exception 'No hay una sesión de caja abierta (%).', p_sesion_caja_id;
  end if;
  if v_rol = 'cajero' and v_ses.cajero_id is distinct from auth.uid() then
    raise exception 'Solo podés cobrar en tu propio turno';
  end if;

  select * into v_perfil from perfil where id = auth.uid();
  v_usuario := coalesce(v_perfil.email, 'sistema');

  -- Ventas: sin duplicados, bloqueadas en orden para evitar deadlocks.
  select array_agg(distinct x order by x) into v_ids from unnest(p_venta_ids) x where x is not null;
  if v_ids is null or array_length(v_ids, 1) = 0 then
    raise exception 'Hay que indicar al menos una VTD a cobrar';
  end if;

  for v_venta in select * from venta where id = any(v_ids) order by id for update loop
    v_n := v_n + 1;
    if v_venta.numero is null or v_venta.numero not like 'VTD-%' then
      raise exception 'La venta % no es una venta directa (VTD)', v_venta.id;
    end if;
    if v_venta.estado = 'ANULADA' then
      raise exception '% está anulada', v_venta.numero;
    end if;
    if not v_venta.cobro_exigible then
      raise exception '% es histórica y está fuera del circuito de cobro', v_venta.numero;
    end if;
    if exists (select 1 from venta_pago where venta_id = v_venta.id) then
      raise exception '% ya tiene un cobro registrado', v_venta.numero;
    end if;
    if coalesce(v_venta.total, 0) <= 0 then
      raise exception '% tiene total 0', v_venta.numero;
    end if;
    v_total := v_total + v_venta.total;
  end loop;
  if v_n <> array_length(v_ids, 1) then
    raise exception 'Alguna de las VTD indicadas no existe';
  end if;

  -- Pagos: solo medios de mostrador; la suma debe dar el total exacto.
  if p_pagos is null or jsonb_typeof(p_pagos) <> 'array' or jsonb_array_length(p_pagos) = 0 then
    raise exception 'p_pagos debe ser un array no vacío';
  end if;
  for v_pago in select * from jsonb_array_elements(p_pagos) loop
    v_metodo := (v_pago ->> 'metodo')::metodo_pago;
    if v_metodo not in ('EFECTIVO', 'QR', 'TRANSFERENCIA') then
      raise exception 'Método % no permitido para VTD (retail): solo EFECTIVO, QR o TRANSFERENCIA', v_metodo;
    end if;
    if coalesce((v_pago ->> 'monto')::numeric, 0) <= 0 then
      raise exception 'Cada pago debe tener monto positivo';
    end if;
    v_recibido := (v_pago ->> 'recibido')::numeric;
    if v_recibido is not null then
      if v_metodo <> 'EFECTIVO' then
        raise exception '"recibido" solo aplica a EFECTIVO';
      end if;
      if v_recibido < (v_pago ->> 'monto')::numeric then
        raise exception 'El monto recibido (%) no puede ser menor al pago (%)', v_recibido, (v_pago ->> 'monto')::numeric;
      end if;
      v_cambio := v_cambio + (v_recibido - (v_pago ->> 'monto')::numeric);
    end if;
    v_pagado := v_pagado + (v_pago ->> 'monto')::numeric;
    v_resto := v_resto || jsonb_build_array(jsonb_build_object(
                 'metodo', v_metodo::text,
                 'monto', (v_pago ->> 'monto')::numeric,
                 'resto', (v_pago ->> 'monto')::numeric,
                 'recibido', v_recibido,
                 'referencia', v_pago ->> 'referencia'));
  end loop;
  if round(v_pagado, 2) <> round(v_total, 2) then
    raise exception 'El pago (%) no coincide con el total de las VTD (%)', v_pagado, v_total;
  end if;

  -- Reparto: se llenan las VTD en orden de id con los pagos en el orden recibido.
  -- Un pago puede partirse entre dos VTD; "recibido" solo se guarda si el pago
  -- entero cae en una sola VTD (el cambio total va en la respuesta).
  v_idx := 0;
  v_n := 0;
  for v_venta in select * from venta where id = any(v_ids) order by id loop
    v_rest_venta := v_venta.total;
    while v_rest_venta > 0 loop
      v_rest_pago := (v_resto -> v_idx ->> 'resto')::numeric;
      if v_rest_pago <= 0 then
        v_idx := v_idx + 1;
        continue;
      end if;
      v_toma   := least(v_rest_pago, v_rest_venta);
      v_metodo := (v_resto -> v_idx ->> 'metodo')::metodo_pago;
      v_verif  := case when v_metodo in ('QR', 'TRANSFERENCIA') then 'PENDIENTE' else 'NO_APLICA' end;
      v_n := v_n + 1;

      insert into venta_pago (venta_id, metodo, monto, recibido, referencia, estado_verificacion)
      values (v_venta.id, v_metodo, v_toma,
              case when v_toma = (v_resto -> v_idx ->> 'monto')::numeric
                   then (v_resto -> v_idx ->> 'recibido')::numeric end,
              v_resto -> v_idx ->> 'referencia', v_verif);

      insert into movimiento_caja (sesion_caja_id, tipo, metodo, monto, venta_id, cliente_id,
                                   creado_por, idempotencia_clave, nota)
      values (p_sesion_caja_id, 'VENTA', v_metodo, v_toma, v_venta.id, v_venta.cliente_id,
              v_usuario, 'cobro_vtd:' || p_idempotencia || ':' || v_n, 'Cobro ' || v_venta.numero);

      v_resto := jsonb_set(v_resto, array[v_idx::text, 'resto'], to_jsonb(v_rest_pago - v_toma));
      v_rest_venta := v_rest_venta - v_toma;
    end loop;

    insert into venta_evento (venta_id, accion, motivo, usuario)
    values (v_venta.id, 'COBRADA', 'Cobro en caja, sesión ' || p_sesion_caja_id, v_usuario);

    v_ventas_out := v_ventas_out || jsonb_build_array(jsonb_build_object(
                      'venta_id', v_venta.id, 'numero', v_venta.numero,
                      'total', v_venta.total, 'estado', v_venta.estado));
  end loop;

  return jsonb_build_object(
    'reintento', false,
    'sesion_caja_id', p_sesion_caja_id,
    'ventas', v_ventas_out,
    'total', v_total,
    'cambio', v_cambio,
    'pendiente_verificacion', exists (
      select 1 from venta_pago where venta_id = any(v_ids) and estado_verificacion = 'PENDIENTE')
  );
end;
